// Sample input for testing this workflow on its own.
// Set STAGE to 'validate' or 'decide', then click "Execute workflow".
const STAGE = 'validate';

const claim = {
  claim_id: 'CLM-0001',
  policy_id: 'POL-1001',
  incident_date: '2026-10-10',
  incident_location: 'Tunis',
  description: 'Rear-ended at a red light. Rear bumper and trunk lid damaged.',
  claimed_amount: 1450,
  photo_count: 3,
  photo_taken_dates: ['2026-10-10', '2026-10-10', '2026-10-11'],
  photo_reused: false,
  has_invoice: true,
};

if (STAGE === 'validate') {
  return [{ json: { stage: 'validate', claim } }];
}

// In the real pipeline the orchestrator passes the output of the validate stage
// and of the three agents. These samples follow their current output formats.
return [{
  json: {
    stage: 'decide',
    claim,
    validation: {
      valid: true,
      reasons: [],
      policy: {
        policy_id: 'POL-1001', product: 'motor_comprehensive', status: 'active',
        start_date: '2026-01-15', end_date: '2027-01-14',
        deductible: 300, coverage_limit: 15000, auto_approval_limit: 2000,
      },
      policy_age_days: 268,
      claims_last_12m: 1,
    },
    // Visual Inspection Agent (Fedi)
    visual: {
      claim_id: 'CLM-0001',
      damage_severity: 2,
      damaged_parts: ['pare-choc arriere', 'coffre'],
      impact_zone: 'arriere',
      matches_description: true,
      mismatch_reason: '',
      pre_existing_damage_signs: false,
      pre_existing_reason: '',
      same_vehicle_across_photos: true,
      suspicious_image_flags: [],
    },
    // Invoice Parser Agent (format still to be agreed)
    invoice: {
      totals_match: true,
      total: 1450,
      line_items: [
        { part: 'Pare-choc arrière', type: 'part', quantity: 1, unit_price: 620 },
        { part: 'Coffre', type: 'part', quantity: 1, unit_price: 480 },
        { part: 'Main d\'oeuvre', type: 'labor', quantity: 5, unit_price: 70 },
      ],
    },
    // Policy RAG Agent (Chedi)
    policy_rag: {
      coverage_status: 'COVERED',
      cited_clauses: ['Section 4.2 - Collision damage'],
      reasoning: 'Collision damage to the insured vehicle is covered.',
      flagged_exclusions: [],
    },
  },
}];

// Checks that the claim has every required field before anything else runs.
return $input.all().map(item => {
  const claim = item.json.claim ?? item.json;
  const errors = [];

  for (const f of ['claim_id', 'policy_id', 'incident_date', 'description', 'claimed_amount']) {
    if (claim[f] === undefined || claim[f] === null || String(claim[f]).trim() === '') {
      errors.push(`Missing field: ${f}`);
    }
  }

  if (claim.incident_date) {
    const d = new Date(claim.incident_date);
    if (isNaN(d)) errors.push('incident_date is not a valid date');
    else if (d > new Date()) errors.push('incident_date is in the future');
  }

  const amount = Number(claim.claimed_amount);
  if (claim.claimed_amount !== undefined && !(amount > 0)) {
    errors.push('claimed_amount must be a positive number');
  }

  const photos = Number(claim.photo_count ?? 0);
  if (photos < 1 || photos > 8) errors.push('photo_count must be between 1 and 8');

  if (claim.has_invoice === false) errors.push('Repair invoice is missing');

  return { json: { claim: { ...claim, claimed_amount: amount }, field_errors: errors } };
});

// Decides whether the claim can go on to the AI agents.
// An invalid claim is rejected here, before any AI call.
const DAY = 24 * 60 * 60 * 1000;

return $input.all().map(item => {
  const { claim, policy, field_errors, prior_claim_dates } = item.json;
  const reasons = [...field_errors];
  let policy_age_days = null;
  let claims_last_12m = 0;

  if (!policy) {
    reasons.push(`Policy ${claim.policy_id} not found`);
  } else {
    const incident = new Date(claim.incident_date);
    const start = new Date(policy.start_date);
    const end = new Date(policy.end_date);

    if (policy.status !== 'active') reasons.push(`Policy status is ${policy.status}`);
    if (incident < start || incident > end) {
      reasons.push(`Incident date ${claim.incident_date} is outside the coverage period (${policy.start_date} to ${policy.end_date})`);
    }

    policy_age_days = Math.floor((incident - start) / DAY);
    claims_last_12m = prior_claim_dates.filter(d => {
      const t = new Date(d);
      return t <= incident && incident - t <= 365 * DAY;
    }).length;
  }

  return {
    json: {
      stage: 'validate',
      claim_id: claim.claim_id,
      valid: reasons.length === 0,
      reasons,
      policy,
      policy_age_days,
      claims_last_12m,
      amount_over_coverage_limit: policy ? claim.claimed_amount > policy.coverage_limit : null,
      checked_at: new Date().toISOString(),
    },
  };
});

// Rule-based part of the risk score (max 60), from section 4.6 of the design.
// Every point comes with a warning sign that explains it.
const norm = s => String(s ?? '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim();

return $input.all().map(item => {
  const { claim = {}, validation = {}, visual, invoice, policy_rag } = item.json;
  const signs = [];
  const add = (code, points, detail) => signs.push({ code, points, detail });

  // An agent that failed or was skipped must not count as "no problem found".
  const missing_inputs = [];
  if (!visual || visual.error) missing_inputs.push('visual');
  if (!invoice || invoice.error) missing_inputs.push('invoice');
  if (!policy_rag || policy_rag.error) missing_inputs.push('policy_rag');
  const v = visual && !visual.error ? visual : {};
  const inv = invoice && !invoice.error ? invoice : {};

  if (claim.photo_reused === true || v.photo_reused === true) {
    add('PHOTO_REUSED', 40, 'Same photo already used in another claim');
  }

  if (v.matches_description === false) {
    add('DAMAGE_MISMATCH', 20, v.mismatch_reason || 'Visible damage inconsistent with the described accident');
  }

  if (inv.totals_match === false) {
    add('INVOICE_ARITHMETIC', 15, inv.arithmetic_issue || 'Invoice arithmetic does not add up');
  }

  const incident = new Date(claim.incident_date);
  const early = (claim.photo_taken_dates || []).filter(d => new Date(d) < incident);
  if (early.length) {
    add('PHOTO_BEFORE_INCIDENT', 15, `${early.length} photo(s) dated before the incident date`);
  }

  const seen = (v.damaged_parts || []).map(norm);
  const notVisible = (inv.line_items || [])
    .filter(li => li.part && li.type !== 'labor')
    .filter(li => {
      const p = norm(li.part);
      return !seen.some(s => s.includes(p) || p.includes(s));
    })
    .map(li => li.part);
  if (notVisible.length && missing_inputs.indexOf('visual') === -1) {
    add('PART_NOT_VISIBLE', Math.min(notVisible.length * 5, 15), `Invoiced part(s) not visible in photos: ${notVisible.join(', ')}`);
  }

  if (v.pre_existing_damage_signs === true) {
    add('PRE_EXISTING_DAMAGE', 10, v.pre_existing_reason || 'Signs of pre-existing damage');
  }

  if (validation.policy_age_days !== null && validation.policy_age_days !== undefined && validation.policy_age_days < 30) {
    add('NEW_POLICY', 10, `Policy only ${validation.policy_age_days} days old at the incident date`);
  }

  if ((validation.claims_last_12m ?? 0) >= 3) {
    add('FREQUENT_CLAIMS', 10, `${validation.claims_last_12m} claims in the last 12 months`);
  }

  const raw = signs.reduce((sum, s) => sum + s.points, 0);

  return {
    json: {
      ...item.json,
      rule_score: Math.min(raw, 60),
      rule_score_uncapped: raw,
      warning_signs: signs,
      missing_inputs,
    },
  };
});

